package com.lore.zzal.chat.line;
import com.lore.zzal.generation.client.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import java.net.http.HttpClient;import java.time.Duration;import java.util.*;
class OpenAiChatUsageRecorderTest {
 @Test void recordsUsageAndIds()throws Exception{try(var stub=new UsageStub()){var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiChatLineClient("SECRET_KEY","minimal",HttpClient.newHttpClient(),stub.endpoint(),64,events::add);var result=c.complete("SECRET_PROMPT","SECRET_USER","gpt-5-mini",Duration.ofSeconds(2));assertThat(result.outputTokens()).isEqualTo(20);assertThat(events).hasSize(1);assertThat(events.getLast().responseId()).isEqualTo("response-test-1");assertThat(events.getLast().xRequestId()).isEqualTo("req-test-1");assertThat(new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(events)).doesNotContain("SECRET");}}
 @Test void timeoutUnknownNoRetry()throws Exception{try(var stub=new UsageStub()){stub.delay=1500;var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiChatLineClient("TEST","minimal",HttpClient.newHttpClient(),stub.endpoint(),64,events::add);assertThatThrownBy(()->c.complete("s","u","gpt-5-mini",Duration.ofMillis(500))).isInstanceOf(java.util.concurrent.TimeoutException.class);assertThat(events.getFirst().usageRaw()).isNull();assertThat(events.getFirst().httpStatus()).isZero();Thread.sleep(1600);assertThat(stub.requests.get()).isEqualTo(1);}}
 @Test void recorderFailureDoesNotRetryOrFailCompletedCall()throws Exception{try(var stub=new UsageStub()){var c=new OpenAiChatLineClient("TEST","minimal",HttpClient.newHttpClient(),stub.endpoint(),64,e->{throw new java.io.IOException("record failed");});assertThatCode(()->c.complete("s","u","gpt-5-mini",Duration.ofSeconds(2))).doesNotThrowAnyException();assertThat(stub.requests.get()).isEqualTo(1);}}
}
